using System;using System.IO;using System.Drawing;using BeamScheduleFormatter;
class AppearancePreferencesTests {
 static int checks;static void Check(bool yes,string why){checks++;if(!yes)throw new Exception(why);}static void Reject(Action action,string why){bool bad=false;try{action();}catch{bad=true;}Check(bad,why);}static double Channel(byte x){double c=x/255.0;return c<=.04045?c/12.92:Math.Pow((c+.055)/1.055,2.4);}static double L(Color c){return .2126*Channel(c.R)+.7152*Channel(c.G)+.0722*Channel(c.B);}static double Contrast(Color a,Color b){return (Math.Max(L(a),L(b))+.05)/(Math.Min(L(a),L(b))+.05);}
 static void Main(){string folder=Path.Combine(Path.GetTempPath(),"DTCE-Appearance-Test-"+Guid.NewGuid().ToString("N"));string path=Path.Combine(folder,"Appearance.xml");try{
  Check(AppearancePreferences.Read(path)==AppearanceMode.System,"Missing setting follows Windows");foreach(AppearanceMode mode in Enum.GetValues(typeof(AppearanceMode))){AppearancePreferences.Write(path,mode);Check(AppearancePreferences.Read(path)==mode,"Preference survives save/reload: "+mode);Check(!File.ReadAllText(path).Contains("1.4."),"Settings schema is independent of application version");}
  foreach(bool systemLight in new[]{false,true}){Check(!AppearancePreferences.ResolveDark(AppearanceMode.Light,systemLight),"Explicit Light ignores Windows dark");Check(AppearancePreferences.ResolveDark(AppearanceMode.Dark,systemLight),"Explicit Dark ignores Windows light");Check(AppearancePreferences.ResolveDark(AppearanceMode.System,systemLight)==!systemLight,"System follows Windows app theme");}
  Reject(()=>AppearancePreferences.Write(path,(AppearanceMode)999),"Unknown mode cannot overwrite saved preference");Check(AppearancePreferences.Read(path)==AppearanceMode.Dark,"Rejected write leaves previous preference intact");
  File.WriteAllText(path,"<DesktopAppearance version='1' mode='Unknown'/>");Reject(()=>AppearancePreferences.Read(path),"Unknown saved value rejected");File.WriteAllText(path,"<DesktopAppearance version='2' mode='Light'/>");Reject(()=>AppearancePreferences.Read(path),"Future schema not silently misread");File.WriteAllText(path,"<!DOCTYPE x [<!ENTITY secret SYSTEM 'file:///nonexistent'>]><DesktopAppearance version='1' mode='Light'>&secret;</DesktopAppearance>");Reject(()=>AppearancePreferences.Read(path),"External entities prohibited");
  foreach(bool dark in new[]{false,true}){var p=new DesktopPalette(dark);Check(Contrast(p.Ink,p.Surface)>=7,"Primary text contrast");Check(Contrast(p.Muted,p.Surface)>=4.5,"Secondary text contrast");Check(Contrast(Color.White,p.Accent)>=4.5,"Primary button text contrast");Check(Contrast(p.Ink,p.Input)>=7,"Input text contrast");Check(p.Tab(0)!=p.Tab(1)&&p.Tab(1)!=p.Tab(2),"Three distinct navigation levels");}
  var light=new DesktopPalette(false);var night=new DesktopPalette(true);Check(light.Translate(night.Ink,night)==light.Ink,"Existing text palette remaps to light");Check(night.Translate(light.Input,light)==night.Input,"Existing input palette remaps to dark");Check(light.Translate(Color.Empty,night).IsEmpty,"Inherited cell colors stay inherited");Check(night.Translate(Color.Red,light)==Color.Red,"Semantic data/error color not replaced");
  Console.WriteLine("PASS: "+checks+" appearance persistence, system policy, safe XML and palette contrast checks");
 }finally{if(Directory.Exists(folder))Directory.Delete(folder,true);}}
}
